window.EP = {"name": "ch6", "label": "एपिसोड 6", "en": "The Village That Never Forgave Hanuman", "duration": 1153.78, "title": [{"start": 5.5, "end": 6.88, "text": "हिडन उत्तराखंड"}, {"start": 7.43, "end": 10.18, "text": "अ बुक बाय, पार्थ डी. जोशी"}, {"start": 10.73, "end": 19.31, "text": "पार्ट टू। सीक्रेट्स अंडर द स्नो। … चैप्टर सिक्स। द विलेज दैट नेवर फ़ॉरगेव हनुमान"}, {"start": 19.86, "end": 22.54, "text": "डे सिक्स। द्रोणागिरी"}], "captions": [{"start": 24.09, "end": 27.87, "text": "इस चैप्टर से पहले, रीडर, मुझे कुछ कन्फ़ेस करना है,", "who": "", "voice": "narrator", "diary": false}, {"start": 27.87, "end": 31.89, "text": "ताकि आप समझ सकें कि इसकी मुझे क्या क़ीमत चुकानी पड़ी।", "who": "", "voice": "narrator", "diary": false}, {"start": 32.34, "end": 37.08, "text": "मैंने अपनी ज़िंदगी के हर एग्ज़ाम से पहले, हनुमान चालीसा पढ़ी है।", "who": "", "voice": "narrator", "diary": false}, {"start": 37.08, "end": 38.34, "text": "स्कूल के एग्ज़ाम।", "who": "", "voice": "narrator", "diary": false}, {"start": 38.34, "end": 40.04, "text": "यूनिवर्सिटी के एग्ज़ाम।", "who": "", "voice": "narrator", "diary": false}, {"start": 40.04, "end": 44.26, "text": "मेरा पीएचडी एंट्रेंस इंटरव्यू, दो बार, एक बार बाथरूम में।", "who": "", "voice": "narrator", "diary": false}, {"start": 44.26, "end": 51.0, "text": "कॉलेज में मेरी डेस्क पर पीतल के एक छोटे से हनुमान जी रखे हैं, और मेरे स्टूडेंट्स जानते हैं,", "who": "", "voice": "narrator", "diary": false}, {"start": 51.0, "end": 53.52, "text": "कि अगर उनका मुँह दीवार की तरफ़ है,", "who": "", "voice": "narrator", "diary": false}, {"start": 53.52, "end": 56.26, "text": "तो मुझसे एक्सटेंशन नहीं माँगना चाहिए।", "who": "", "voice": "narrator", "diary": false}, {"start": 56.71, "end": 58.39, "text": "और शनिवार की सुबह,", "who": "", "voice": "narrator", "diary": false}, {"start": 58.39, "end": 65.22, "text": "हम भारत के उस इकलौते गाँव की तरफ़ चले… जिसने उन्हें आज तक माफ़ नहीं किया।", "who": "", "voice": "narrator", "diary": false}, {"start": 66.72, "end": 69.14, "text": "ये सब एक रात पहले शुरू हुआ,", "who": "", "voice": "narrator", "diary": false}, {"start": 69.14, "end": 73.79, "text": "चोपता के एक सस्ते कमरे में, शाओनी के चक्कर लगाने से।", "who": "", "voice": "narrator", "diary": false}, {"start": 74.24, "end": 75.26, "text": "अकेले नहीं जाओगे।", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 75.46, "end": 77.36, "text": "उसने मुझसे कहा, नौवीं बार।", "who": "", "voice": "narrator", "diary": false}, {"start": 77.56, "end": 78.0, "text": "औली।", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 78.0, "end": 78.55, "text": "संडे।", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 78.55, "end": 79.22, "text": "अकेले।", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 79.22, "end": 81.32, "text": "ये ट्रैप है, पार्थ।", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 81.32, "end": 82.65, "text": "बेसिक लॉजिक।", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 83.1, "end": 84.03, "text": "तो क्या करें?", "who": "", "voice": "narrator", "diary": false}, {"start": 84.23, "end": 85.35, "text": "मैंने उससे पूछा।", "who": "", "voice": "narrator", "diary": false}, {"start": 85.8, "end": 90.11, "text": "उसने चक्कर लगाना बंद किया, और क्षितिज की डायरी थपथपाई,", "who": "", "voice": "narrator", "diary": false}, {"start": 90.11, "end": 92.83, "text": "जो हम दोनों के बीच बेड पर खुली थी।", "who": "", "voice": "narrator", "diary": false}, {"start": 93.28, "end": 96.96, "text": "उससे पहले वहाँ पहुँचो, जहाँ वो अभी तक नहीं पहुँचा।", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 97.16, "end": 99.16, "text": "उसने एक नाम पर उँगली रखी।", "who": "", "voice": "narrator", "diary": false}, {"start": 99.36, "end": 100.73, "text": "प्रताप सिंह रावत।", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 100.73, "end": 101.61, "text": "द्रोणागिरी।", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 101.61, "end": 106.43, "text": "अगर उन्नीस सौ छियासठ में किसी ने गरम शिला सबसे पहले देखी थी,", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 106.43, "end": 109.81, "text": "तो उनके घर में कोई न कोई ज़रूर जानता होगा।", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 110.26, "end": 111.84, "text": "क्षितिज ने उसकी तरफ़ देखा।", "who": "", "voice": "narrator", "diary": false}, {"start": 112.04, "end": 114.05, "text": "और अगर रोहन भी वही सोच रहा हो?", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 114.5, "end": 116.36, "text": "तो हम उससे पहले पहुँचेंगे।", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 116.56, "end": 117.42, "text": "शाओनी ने कहा।", "who": "", "voice": "narrator", "diary": false}, {"start": 117.62, "end": 119.55, "text": "कल सुबह, पाँच बजे।", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 120.0, "end": 125.11, "text": "गब्बर, जो दरवाज़े के पास प्लास्टिक की कुर्सी पर आधा सोया हुआ था,", "who": "", "voice": "narrator", "diary": false}, {"start": 125.11, "end": 126.46, "text": "उसने एक आँख खोली।", "who": "", "voice": "narrator", "diary": false}, {"start": 126.66, "end": 127.78, "text": "साढ़े पाँच, दीदी।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 127.78, "end": 129.28, "text": "बसंती को भी नींद चाहिए।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 130.78, "end": 135.49, "text": "तो शनिवार को, हम चोपता से नीचे अलकनंदा तक गए, और ऊपर जोशीमठ तक।", "who": "", "voice": "narrator", "diary": false}, {"start": 135.94, "end": 141.68, "text": "जोशीमठ में, गब्बर ने टीन की छत वाली एक चाय की दुकान के बाहर बसंती रोकी,", "who": "", "voice": "narrator", "diary": false}, {"start": 141.68, "end": 143.62, "text": "और हॉर्न पर हाथ रख दिया।", "who": "", "voice": "narrator", "diary": false}, {"start": 143.62, "end": 147.74, "text": "तीस-पैंतीस साल का एक आदमी, हाथ में अभी भी कलछी लिए,", "who": "", "voice": "narrator", "diary": false}, {"start": 147.74, "end": 151.7, "text": "दौड़ता हुआ बाहर आया, और गब्बर के गले से लिपट गया।", "who": "", "voice": "narrator", "diary": false}, {"start": 152.15, "end": 152.86, "text": "महेश।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 153.06, "end": 157.93, "text": "गब्बर ने हम तीनों से घोषणा की, ख़ुद को छुड़ाते हुए, उस गर्व के साथ,", "who": "", "voice": "narrator", "diary": false}, {"start": 157.93, "end": 161.56, "text": "जैसे कोई किसी मिनिस्टर का इंट्रोडक्शन करवा रहा हो।", "who": "", "voice": "narrator", "diary": false}, {"start": 161.76, "end": 162.95, "text": "मेरे मामा का बेटा।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 162.95, "end": 167.13, "text": "हल्द्वानी में, बचपन में हम दोनों एक ही साइकिल पे स्कूल जाते थे।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 167.13, "end": 168.72, "text": "बाद में ये जोशीमठ आ गया।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 168.72, "end": 170.77, "text": "ये चलाता था, मैं पीछे बैठता था,", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 170.77, "end": 173.02, "text": "और जब भी गिरे… ग़लती मेरी होती थी।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 173.47, "end": 175.18, "text": "अभी भी तेरी ही होती है।", "who": "महेश", "voice": "mahesh", "diary": false}, {"start": 175.38, "end": 177.38, "text": "महेश ने मुस्कुराते हुए उससे कहा।", "who": "", "voice": "narrator", "diary": false}, {"start": 177.83, "end": 183.17, "text": "उसका गोल, ख़ुशमिज़ाज चेहरा था, फ़ोन के पीछे क्रिकेट बैट का स्टिकर,", "who": "", "voice": "narrator", "diary": false}, {"start": 183.17, "end": 187.22, "text": "और ऐसी एनर्जी, जो आपसे वो दूसरी चाय भी ख़रीदवा दे,", "who": "", "voice": "narrator", "diary": false}, {"start": 187.22, "end": 189.0, "text": "जो आपको नहीं चाहिए थी।", "who": "", "voice": "narrator", "diary": false}, {"start": 189.0, "end": 193.2, "text": "उसने मुझे बताया, ऑफ़-सीज़न में वो ये दुकान चलाता है,", "who": "", "voice": "narrator", "diary": false}, {"start": 193.2, "end": 196.69, "text": "स्की सीज़न में ऊपर औली में एक चाय की दुकान,", "who": "", "voice": "narrator", "diary": false}, {"start": 196.69, "end": 198.87, "text": "और बीच में टैक्सी चलाता है।", "who": "", "voice": "narrator", "diary": false}, {"start": 199.32, "end": 200.72, "text": "तीन धंधे, प्रोफ़ेसर साहब।", "who": "महेश", "voice": "mahesh", "diary": false}, {"start": 200.72, "end": 202.4, "text": "फिर भी ई-एम-आई पूरी नहीं होती।", "who": "महेश", "voice": "mahesh", "diary": false}, {"start": 202.6, "end": 203.24, "text": "वो हँसा।", "who": "", "voice": "narrator", "diary": false}, {"start": 203.44, "end": 207.36, "text": "जोशीमठ में दरार आई, तो टूरिस्ट भी दरार देख के भाग गए।", "who": "महेश", "voice": "mahesh", "diary": false}, {"start": 207.81, "end": 208.81, "text": "वो एक जोक था।", "who": "", "voice": "narrator", "diary": false}, {"start": 208.81, "end": 211.57, "text": "लेकिन उसकी हँसी… थोड़ा जल्दी रुक गई।", "who": "", "voice": "narrator", "diary": false}, {"start": 212.02, "end": 218.21, "text": "जब गब्बर ने उसे बताया, कि हम द्रोणागिरी के प्रताप सिंह रावत के परिवार को ढूँढ रहे हैं,", "who": "", "voice": "narrator", "diary": false}, {"start": 218.21, "end": 224.18, "text": "तो महेश को ठीक-ठीक पता था कि हमें किससे पूछना चाहिए: कमला देवी नाम की एक बूढ़ी औरत,", "who": "", "voice": "narrator", "diary": false}, {"start": 224.18, "end": 227.49, "text": "गाँव में आख़िरी इंसान, जिन्हें प्रताप याद हैं।", "who": "", "voice": "narrator", "diary": false}, {"start": 227.49, "end": 230.79, "text": "उसने एक पेपर नैपकिन पर हमारे लिए नक़्शा बनाया।", "who": "", "voice": "narrator", "diary": false}, {"start": 230.79, "end": 234.39, "text": "फिर उसने गब्बर से पूछा, कि हम उस रात कहाँ रुकेंगे,", "who": "", "voice": "narrator", "diary": false}, {"start": 234.39, "end": 237.7, "text": "और कितने दिन, और हम ठीक-ठीक क्या ढूँढ रहे हैं।", "who": "", "voice": "narrator", "diary": false}, {"start": 237.7, "end": 238.7, "text": "दोस्ताना सवाल।", "who": "", "voice": "narrator", "diary": false}, {"start": 238.7, "end": 240.86, "text": "वो सवाल, जो एक कज़िन पूछता है।", "who": "", "voice": "narrator", "diary": false}, {"start": 241.31, "end": 242.89, "text": "गब्बर ने सबका जवाब दिया।", "who": "", "voice": "narrator", "diary": false}, {"start": 242.89, "end": 243.94, "text": "ज़ाहिर है, दिया।", "who": "", "voice": "narrator", "diary": false}, {"start": 243.94, "end": 246.3, "text": "आप उस लड़के से कोई राज़ नहीं छुपाते,", "who": "", "voice": "narrator", "diary": false}, {"start": 246.3, "end": 248.59, "text": "जो आपको साइकिल पर स्कूल ले जाता था।", "who": "", "voice": "narrator", "diary": false}, {"start": 249.04, "end": 252.64, "text": "क्षितिज ने आदत से, दुकान का नाम अपनी डायरी में लिख लिया।", "who": "", "voice": "narrator", "diary": false}, {"start": 252.64, "end": 254.37, "text": "मुझे याद है, मैंने सोचा था,", "who": "", "voice": "narrator", "diary": false}, {"start": 254.37, "end": 256.81, "text": "ये उसकी थोड़ी ज़्यादा ही शक्की आदत है।", "who": "", "voice": "narrator", "diary": false}, {"start": 258.31, "end": 263.87, "text": "जोशीमठ से, हम पूरब की तरफ़, धौलीगंगा घाटी में गए, सड़क पतली होती गई,", "who": "", "voice": "narrator", "diary": false}, {"start": 263.87, "end": 267.14, "text": "चढ़ती गई, जब तक कि जुम्मा नाम की जगह पर,", "who": "", "voice": "narrator", "diary": false}, {"start": 267.14, "end": 269.6, "text": "उसने पूरी तरह हार नहीं मान ली।", "who": "", "voice": "narrator", "diary": false}, {"start": 269.6, "end": 271.72, "text": "वहाँ से, आप पैदल चलते हैं।", "who": "", "voice": "narrator", "diary": false}, {"start": 272.17, "end": 281.03, "text": "द्रोणागिरी का रास्ता भोजपत्र और चीड़ के बीच से चढ़ता है, और फिर पेड़ों के ऊपर निकलकर, ऊँचे चरागाह के एक चौड़े,", "who": "", "voice": "narrator", "diary": false}, {"start": 281.03, "end": 286.5, "text": "नंगे पठार पर पहुँचता है, जो इतने पास, इतने सफ़ेद पहाड़ों से घिरा है,", "who": "", "voice": "narrator", "diary": false}, {"start": 286.5, "end": 289.4, "text": "कि लगे, काग़ज़ से काटकर बनाए गए हों।", "who": "", "voice": "narrator", "diary": false}, {"start": 289.4, "end": 293.82, "text": "घाटी के उस पार, एक पहाड़ बाक़ियों से थोड़ा अलग खड़ा था।", "who": "", "voice": "narrator", "diary": false}, {"start": 293.82, "end": 296.32, "text": "उसकी दाईं ढलान… ग़लत लग रही थी।", "who": "", "voice": "narrator", "diary": false}, {"start": 296.32, "end": 298.09, "text": "ठीक-ठीक टूटी हुई नहीं।", "who": "", "voice": "narrator", "diary": false}, {"start": 298.09, "end": 298.89, "text": "खुरची हुई।", "who": "", "voice": "narrator", "diary": false}, {"start": 298.89, "end": 302.51, "text": "जैसे किसी दैत्य ने उसमें से एक बाइट ले ली हो।", "who": "", "voice": "narrator", "diary": false}, {"start": 302.96, "end": 305.28, "text": "गब्बर रास्ते पर रुका, और इशारा किया।", "who": "", "voice": "narrator", "diary": false}, {"start": 305.48, "end": 306.68, "text": "द्रोणागिरी पर्वत।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 306.88, "end": 309.26, "text": "उसने धीरे से हमें बताया।", "who": "", "voice": "narrator", "diary": false}, {"start": 309.46, "end": 310.49, "text": "इनका देवता।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 311.19, "end": 312.04, "text": "मैं रुक गया।", "who": "", "voice": "narrator", "diary": false}, {"start": 312.04, "end": 312.68, "text": "शाओनी भी।", "who": "", "voice": "narrator", "diary": false}, {"start": 313.38, "end": 315.84, "text": "आपको कहानी पता है, मुझे लगता है।", "who": "", "voice": "narrator", "diary": false}, {"start": 315.84, "end": 317.46, "text": "भारत में सबको पता है।", "who": "", "voice": "narrator", "diary": false}, {"start": 317.46, "end": 320.7, "text": "रामायण में, लक्ष्मण लंका के रणक्षेत्र में,", "who": "", "voice": "narrator", "diary": false}, {"start": 320.7, "end": 324.39, "text": "मेघनाद के अस्त्र से घायल, मौत के क़रीब पड़े हैं।", "who": "", "voice": "narrator", "diary": false}, {"start": 324.39, "end": 327.4, "text": "इकलौता इलाज है, संजीवनी नाम की एक बूटी,", "who": "", "voice": "narrator", "diary": false}, {"start": 327.4, "end": 329.94, "text": "जो हिमालय के एक पहाड़ पर उगती है।", "who": "", "voice": "narrator", "diary": false}, {"start": 329.94, "end": 332.87, "text": "हनुमान उसे लेने उत्तर की ओर उड़ते हैं।", "who": "", "voice": "narrator", "diary": false}, {"start": 332.87, "end": 335.41, "text": "लेकिन जब वो पहाड़ पर पहुँचते हैं,", "who": "", "voice": "narrator", "diary": false}, {"start": 335.41, "end": 338.65, "text": "तो पहचान नहीं पाते, कि सही पौधा कौन सा है।", "who": "", "voice": "narrator", "diary": false}, {"start": 338.65, "end": 343.42, "text": "तो, जैसे मेरे बचपन की हर कॉमिक बुक ने शानदार रंगों में दिखाया,", "who": "", "voice": "narrator", "diary": false}, {"start": 343.42, "end": 346.35, "text": "वो पूरा पहाड़ उठाकर, लंका ले जाते हैं।", "who": "", "voice": "narrator", "diary": false}, {"start": 346.8, "end": 347.13, "text": "वीर।", "who": "", "voice": "narrator", "diary": false}, {"start": 347.13, "end": 347.54, "text": "भक्त।", "who": "", "voice": "narrator", "diary": false}, {"start": 347.54, "end": 352.2, "text": "एक कहानी, जिसे मैं चार साल की उम्र से प्यार करता आया हूँ।", "who": "", "voice": "narrator", "diary": false}, {"start": 352.65, "end": 356.64, "text": "अब मैं उस गाँव में खड़ा था… जिसने वो पहाड़ खोया था।", "who": "", "voice": "narrator", "diary": false}, {"start": 358.14, "end": 360.86, "text": "जब हम पहुँचे, द्रोणागिरी आधा ख़ाली था।", "who": "", "voice": "narrator", "diary": false}, {"start": 360.86, "end": 363.93, "text": "अक्टूबर का आख़िर था, और गाँव वही कर रहा था,", "who": "", "voice": "narrator", "diary": false}, {"start": 363.93, "end": 367.58, "text": "जो हर साल बर्फ़ से पहले करता है: सामान बाँध रहा था।", "who": "", "voice": "narrator", "diary": false}, {"start": 367.58, "end": 375.38, "text": "यहाँ के परिवार भोटिया हैं, ऊँचे पहाड़ों के लोग, जो गर्मियाँ यहाँ ऊपर अपने रेवड़ों और खेतों के साथ बिताते हैं,", "who": "", "voice": "narrator", "diary": false}, {"start": 375.38, "end": 379.09, "text": "और सर्दियों के लिए नीचे गरम गाँवों में चले जाते हैं।", "who": "", "voice": "narrator", "diary": false}, {"start": 379.09, "end": 381.03, "text": "दरवाज़ों पर ताले लग रहे थे।", "who": "", "voice": "narrator", "diary": false}, {"start": 381.03, "end": 382.74, "text": "बकरियाँ गिनी जा रही थीं।", "who": "", "voice": "narrator", "diary": false}, {"start": 382.74, "end": 385.82, "text": "एक बूढ़ा आदमी, किसी सर्जन जैसी एकाग्रता से,", "who": "", "voice": "narrator", "diary": false}, {"start": 385.82, "end": 388.46, "text": "टीन का एक बक्सा खच्चर पर बाँध रहा था।", "who": "", "voice": "narrator", "diary": false}, {"start": 388.91, "end": 395.2, "text": "जिस औरत को ढूँढने के लिए महेश ने कहा था, वो इस सबके बीच एक पत्थर के चबूतरे पर बैठी,", "who": "", "voice": "narrator", "diary": false}, {"start": 395.2, "end": 400.12, "text": "सेम छील रही थीं, जैसे सर्दियों के लिए जाना एक छोटी सी असुविधा हो,", "who": "", "voice": "narrator", "diary": false}, {"start": 400.12, "end": 402.31, "text": "जो वो अस्सी बार झेल चुकी हों।", "who": "", "voice": "narrator", "diary": false}, {"start": 402.31, "end": 403.75, "text": "जो वो झेल चुकी थीं।", "who": "", "voice": "narrator", "diary": false}, {"start": 404.2, "end": 406.04, "text": "उनका नाम कमला देवी था।", "who": "", "voice": "narrator", "diary": false}, {"start": 406.04, "end": 406.95, "text": "छियासी साल।", "who": "", "voice": "narrator", "diary": false}, {"start": 406.95, "end": 412.87, "text": "छोटी, तेज़ आँखों वाली, काली ऊनी पंखी में लिपटी, नाक और कानों में चाँदी,", "who": "", "voice": "narrator", "diary": false}, {"start": 412.87, "end": 418.03, "text": "और ऐसी नज़र, जो लगभग आधे सेकंड में हम तीनों के आर-पार निकल गई।", "who": "", "voice": "narrator", "diary": false}, {"start": 418.48, "end": 422.17, "text": "गब्बर उनके पास बैठा, और गढ़वाली में समझाया,", "who": "", "voice": "narrator", "diary": false}, {"start": 422.17, "end": 425.26, "text": "कि हम कौन हैं, और किसे ढूँढ रहे हैं।", "who": "", "voice": "narrator", "diary": false}, {"start": 425.26, "end": 427.92, "text": "उन्होंने सेम छीलना बंद कर दिया।", "who": "", "voice": "narrator", "diary": false}, {"start": 428.37, "end": 429.0, "text": "प्रताप।", "who": "कमला देवी", "voice": "kamla", "diary": false}, {"start": 429.2, "end": 430.63, "text": "उन्होंने मुझसे हिंदी में कहा।", "who": "", "voice": "narrator", "diary": false}, {"start": 430.83, "end": 432.4, "text": "मेरी बहन का आदमी था।", "who": "कमला देवी", "voice": "kamla", "diary": false}, {"start": 433.9, "end": 439.34, "text": "लेकिन पहले, क्योंकि ये एक पहाड़ी गाँव है, और चाय से पहले कुछ नहीं होता,", "who": "", "voice": "narrator", "diary": false}, {"start": 439.34, "end": 443.78, "text": "उन्होंने हमें चबूतरे पर बिठाया, और एक बर्तन उबलने रख दिया।", "who": "", "voice": "narrator", "diary": false}, {"start": 443.78, "end": 448.06, "text": "और जब तक वो उबला, क्षितिज ने, जिसने भी वो पहाड़ देखा था,", "who": "", "voice": "narrator", "diary": false}, {"start": 448.06, "end": 450.28, "text": "उनसे हनुमान के बारे में पूछा।", "who": "", "voice": "narrator", "diary": false}, {"start": 450.73, "end": 451.71, "text": "उन्होंने बताया।", "who": "", "voice": "narrator", "diary": false}, {"start": 451.71, "end": 455.25, "text": "और मैं ये आपको वैसे ही सुनाऊँगा, जैसे उन्होंने सुनाया,", "who": "", "voice": "narrator", "diary": false}, {"start": 455.25, "end": 459.37, "text": "क्योंकि ये उनके गाँव की कहानी है, और वो मज़ाक़ नहीं कर रही थीं।", "who": "", "voice": "narrator", "diary": false}, {"start": 459.82, "end": 464.43, "text": "द्रोणागिरी के लोग अपने पहाड़ को पूजते हैं, उन्होंने बताया।", "who": "", "voice": "narrator", "diary": false}, {"start": 464.43, "end": 467.69, "text": "पहाड़ पर किसी देवता को नहीं: पहाड़ को ही।", "who": "", "voice": "narrator", "diary": false}, {"start": 467.69, "end": 468.49, "text": "पर्वत देव।", "who": "", "voice": "narrator", "diary": false}, {"start": 468.49, "end": 470.79, "text": "जब हनुमान बूटी ढूँढते हुए आए,", "who": "", "voice": "narrator", "diary": false}, {"start": 470.79, "end": 474.45, "text": "गाँव वालों ने उनकी मदद नहीं की; पहाड़ उनका था,", "who": "", "voice": "narrator", "diary": false}, {"start": 474.45, "end": 475.96, "text": "और उसकी बूटियाँ भी।", "who": "", "voice": "narrator", "diary": false}, {"start": 475.96, "end": 479.62, "text": "तो हनुमान ने एक ग़रीब बूढ़े साधु का भेस बनाया,", "who": "", "voice": "narrator", "diary": false}, {"start": 479.62, "end": 483.2, "text": "गाँव की एक बूढ़ी औरत के पास गए, और भीख माँगी।", "who": "", "voice": "narrator", "diary": false}, {"start": 483.2, "end": 486.06, "text": "वक़्त निकला जा रहा था, उन्होंने कहा।", "who": "", "voice": "narrator", "diary": false}, {"start": 486.06, "end": 487.09, "text": "कोई मर जाएगा।", "who": "", "voice": "narrator", "diary": false}, {"start": 487.54, "end": 489.21, "text": "उस औरत को उन पर तरस आया।", "who": "", "voice": "narrator", "diary": false}, {"start": 489.21, "end": 490.54, "text": "उसने इशारा कर दिया।", "who": "", "voice": "narrator", "diary": false}, {"start": 490.99, "end": 493.12, "text": "और हनुमान ने कोई बूटी नहीं ली।", "who": "", "voice": "narrator", "diary": false}, {"start": 493.12, "end": 497.39, "text": "उन्होंने पहाड़ का पूरा एक हिस्सा उखाड़ा… और उसे लेकर उड़ गए।", "who": "", "voice": "narrator", "diary": false}, {"start": 497.84, "end": 498.28, "text": "देख लो।", "who": "कमला देवी", "voice": "kamla", "diary": false}, {"start": 498.48, "end": 500.54, "text": "कमला देवी ने हमसे कहा,", "who": "", "voice": "narrator", "diary": false}, {"start": 500.54, "end": 505.5, "text": "घाटी के उस पार खुरची हुई ढलान की तरफ़ सिर हिलाते हुए।", "who": "", "voice": "narrator", "diary": false}, {"start": 505.7, "end": 506.52, "text": "आज भी।", "who": "कमला देवी", "voice": "kamla", "diary": false}, {"start": 506.97, "end": 510.3, "text": "गाँव ने उस बूढ़ी औरत को सज़ा दी, उन्होंने बताया।", "who": "", "voice": "narrator", "diary": false}, {"start": 510.3, "end": 511.34, "text": "उसे निकाल दिया।", "who": "", "voice": "narrator", "diary": false}, {"start": 511.34, "end": 512.25, "text": "और उस दिन से,", "who": "", "voice": "narrator", "diary": false}, {"start": 512.25, "end": 517.1, "text": "द्रोणागिरी की औरतों को पहाड़ की पूजा में शामिल होने की इजाज़त नहीं है।", "who": "", "voice": "narrator", "diary": false}, {"start": 517.1, "end": 519.19, "text": "पर्वत देव की बड़ी पूजा के दिन,", "who": "", "voice": "narrator", "diary": false}, {"start": 519.19, "end": 521.82, "text": "औरतें आदमियों को खाना भी नहीं परोसतीं।", "who": "", "voice": "narrator", "diary": false}, {"start": 522.27, "end": 523.2, "text": "और हनुमान जी?", "who": "", "voice": "narrator", "diary": false}, {"start": 523.4, "end": 524.84, "text": "मैंने उनसे पूछा।", "who": "", "voice": "narrator", "diary": false}, {"start": 524.84, "end": 529.13, "text": "मेरी आवाज़, जितना मैं चाहता था, उससे छोटी निकली।", "who": "", "voice": "narrator", "diary": false}, {"start": 529.58, "end": 531.56, "text": "इस गाँव में उनकी पूजा नहीं होती।", "who": "कमला देवी", "voice": "kamla", "diary": false}, {"start": 531.76, "end": 533.36, "text": "उन्होंने सीधे-सीधे कहा।", "who": "", "voice": "narrator", "diary": false}, {"start": 533.56, "end": 535.45, "text": "लाल झंडा नहीं लगता।", "who": "कमला देवी", "voice": "kamla", "diary": false}, {"start": 535.45, "end": 537.63, "text": "और जब रामलीला होती है…", "who": "कमला देवी", "voice": "kamla", "diary": false}, {"start": 537.83, "end": 539.02, "text": "उन्होंने हाथ फैलाए।", "who": "", "voice": "narrator", "diary": false}, {"start": 539.22, "end": 541.2, "text": "हनुमान नहीं आते।", "who": "कमला देवी", "voice": "kamla", "diary": false}, {"start": 541.2, "end": 542.19, "text": "राम हैं।", "who": "कमला देवी", "voice": "kamla", "diary": false}, {"start": 542.19, "end": 543.3, "text": "सीता हैं।", "who": "कमला देवी", "voice": "kamla", "diary": false}, {"start": 543.3, "end": 544.29, "text": "रावण है।", "who": "कमला देवी", "voice": "kamla", "diary": false}, {"start": 544.29, "end": 545.77, "text": "हनुमान नहीं।", "who": "कमला देवी", "voice": "kamla", "diary": false}, {"start": 546.22, "end": 547.88, "text": "क्षितिज का पेन जम गया।", "who": "", "voice": "narrator", "diary": false}, {"start": 548.08, "end": 549.87, "text": "रामलीला… बिना हनुमान के?", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 550.07, "end": 551.17, "text": "उसने उनसे पूछा।", "who": "", "voice": "narrator", "diary": false}, {"start": 551.37, "end": 553.31, "text": "फिर लंका कौन जलाता है?", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 553.76, "end": 556.7, "text": "कमला देवी ने उसे एक लंबे पल तक देखा।", "who": "", "voice": "narrator", "diary": false}, {"start": 556.7, "end": 560.95, "text": "फिर वो हँसीं: एक बड़ी, खिलखिलाती, ख़ुशी से भरी हँसी,", "who": "", "voice": "narrator", "diary": false}, {"start": 560.95, "end": 563.9, "text": "जिससे पास से गुज़रती एक बकरी उछल गई।", "who": "", "voice": "narrator", "diary": false}, {"start": 564.35, "end": 566.64, "text": "बेटा, ये हमारा गाँव है।", "who": "कमला देवी", "voice": "kamla", "diary": false}, {"start": 566.64, "end": 567.84, "text": "हमारी कहानी।", "who": "कमला देवी", "voice": "kamla", "diary": false}, {"start": 568.04, "end": 571.31, "text": "उन्होंने सेम की एक फली उसकी तरफ़ हिलाई।", "who": "", "voice": "narrator", "diary": false}, {"start": 571.51, "end": 573.42, "text": "हमने उसे माफ़ नहीं किया।", "who": "कमला देवी", "voice": "kamla", "diary": false}, {"start": 573.42, "end": 574.77, "text": "बाक़ी दुनिया करे।", "who": "कमला देवी", "voice": "kamla", "diary": false}, {"start": 574.77, "end": 575.4, "text": "हम नहीं।", "who": "कमला देवी", "voice": "kamla", "diary": false}, {"start": 575.85, "end": 581.86, "text": "मैं अपनी चाय लिए वहाँ बैठा रहा, ज़िंदगी भर का एक हनुमान भक्त, एक ऐसे गाँव में,", "who": "", "voice": "narrator", "diary": false}, {"start": 581.86, "end": 586.63, "text": "जहाँ हनुमान विलेन थे, और मैंने आस्था के बारे में कुछ ऐसा सीखा,", "who": "", "voice": "narrator", "diary": false}, {"start": 586.63, "end": 588.25, "text": "जो मैं नहीं जानता था।", "who": "", "voice": "narrator", "diary": false}, {"start": 588.7, "end": 590.18, "text": "वो लोकल हो सकती है।", "who": "", "voice": "narrator", "diary": false}, {"start": 590.18, "end": 592.2, "text": "वो किसी जगह की हो सकती है।", "who": "", "voice": "narrator", "diary": false}, {"start": 592.2, "end": 595.85, "text": "जिस कहानी ने मुझे हर एग्ज़ाम से पहले हिम्मत दी,", "who": "", "voice": "narrator", "diary": false}, {"start": 595.85, "end": 598.34, "text": "उसी ने इन लोगों से कुछ छीन लिया।", "who": "", "voice": "narrator", "diary": false}, {"start": 598.34, "end": 599.66, "text": "हम दोनों सही हैं।", "who": "", "voice": "narrator", "diary": false}, {"start": 599.66, "end": 603.24, "text": "उस रात, मैंने अपनी नोटबुक में लिखा: वही भगवान।", "who": "", "voice": "narrator", "diary": false}, {"start": 603.24, "end": 604.02, "text": "वही कहानी।", "who": "", "voice": "narrator", "diary": false}, {"start": 604.02, "end": 605.57, "text": "पहाड़ की दूसरी तरफ़।", "who": "", "voice": "narrator", "diary": false}, {"start": 606.02, "end": 608.67, "text": "मैंने द्रोणागिरी में चालीसा नहीं पढ़ी।", "who": "", "voice": "narrator", "diary": false}, {"start": 608.67, "end": 609.72, "text": "मन में भी नहीं।", "who": "", "voice": "narrator", "diary": false}, {"start": 609.72, "end": 611.18, "text": "ये मेरा गाँव नहीं था।", "who": "", "voice": "narrator", "diary": false}, {"start": 611.63, "end": 615.94, "text": "लेकिन मैं मानता हूँ, कि बाहर निकलते हुए, मैं मुड़ा,", "who": "", "voice": "narrator", "diary": false}, {"start": 615.94, "end": 621.34, "text": "उस खुरचे हुए पहाड़ को देखा, और बहुत धीरे से कहा: सॉरी, बजरंगबली।", "who": "", "voice": "narrator", "diary": false}, {"start": 621.34, "end": 623.03, "text": "आज आपका दिन नहीं था।", "who": "", "voice": "narrator", "diary": false}, {"start": 624.53, "end": 626.6, "text": "फिर उन्होंने हमें प्रताप के बारे में बताया।", "who": "", "voice": "narrator", "diary": false}, {"start": 627.05, "end": 633.47, "text": "वो एक चरवाहा था, उन्नीस सौ छियासठ में एक जवान आदमी, उन्होंने बताया: मज़बूत,", "who": "", "voice": "narrator", "diary": false}, {"start": 633.47, "end": 634.83, "text": "शांत, उस तरह का,", "who": "", "voice": "narrator", "diary": false}, {"start": 634.83, "end": 639.03, "text": "जो धुंध में भी पहाड़ की ढलान पर खोई बकरी ढूँढ ले।", "who": "", "voice": "narrator", "diary": false}, {"start": 639.03, "end": 646.3, "text": "उस बसंत में, बहुत जल्दी, बर्फ़ जाने से पहले, वो और उसके दो दोस्त कुछ जानवरों को लेकर,", "who": "", "voice": "narrator", "diary": false}, {"start": 646.3, "end": 650.49, "text": "बड़ी चोटियों के नीचे के ऊँचे चरागाहों की तरफ़ गए,", "who": "", "voice": "narrator", "diary": false}, {"start": 650.49, "end": 653.49, "text": "उससे पहले, जब कोई आमतौर पर जाता था।", "who": "", "voice": "narrator", "diary": false}, {"start": 653.94, "end": 655.15, "text": "छह दिन बाद लौटे।", "who": "कमला देवी", "voice": "kamla", "diary": false}, {"start": 655.35, "end": 656.45, "text": "उन्होंने हमें बताया।", "who": "", "voice": "narrator", "diary": false}, {"start": 656.65, "end": 658.96, "text": "और किसी से बात नहीं की।", "who": "कमला देवी", "voice": "kamla", "diary": false}, {"start": 658.96, "end": 660.27, "text": "किसी से नहीं।", "who": "कमला देवी", "voice": "kamla", "diary": false}, {"start": 660.27, "end": 661.27, "text": "महीनों तक।", "who": "कमला देवी", "voice": "kamla", "diary": false}, {"start": 661.72, "end": 662.03, "text": "फिर?", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 662.23, "end": 664.3, "text": "शाओनी ने धीरे से उनसे पूछा।", "who": "", "voice": "narrator", "diary": false}, {"start": 664.75, "end": 667.29, "text": "फिर एक दिन, प्रताप ने गीत बना दिया।", "who": "कमला देवी", "voice": "kamla", "diary": false}, {"start": 667.29, "end": 669.24, "text": "पहाड़ी लोग ऐसे ही करते हैं।", "who": "कमला देवी", "voice": "kamla", "diary": false}, {"start": 669.24, "end": 671.63, "text": "जो बोल नहीं सकते… वो गा देते हैं।", "who": "कमला देवी", "voice": "kamla", "diary": false}, {"start": 672.08, "end": 674.06, "text": "उन्होंने आँखें बंद कीं, और गाया।", "who": "", "voice": "narrator", "diary": false}, {"start": 674.51, "end": 678.55, "text": "पहली चार लाइनें हमारे पास पहले से थीं, और उन्होंने वो गाईं।", "who": "", "voice": "narrator", "diary": false}, {"start": 678.55, "end": 682.6, "text": "फिर वो दो लाइनें, जो हमने मलेथा में बची राम जी से सुनी थीं,", "who": "", "voice": "narrator", "diary": false}, {"start": 682.6, "end": 684.79, "text": "बर्फ़ में सोए पत्थर के बारे में।", "who": "", "voice": "narrator", "diary": false}, {"start": 684.79, "end": 688.9, "text": "और फिर, क्षितिज ने मेरी बाँह इतनी ज़ोर से पकड़ी कि दर्द हुआ,", "who": "", "voice": "narrator", "diary": false}, {"start": 688.9, "end": 692.26, "text": "दो लाइनें, जो हममें से किसी ने कभी नहीं सुनी थीं:", "who": "", "voice": "narrator", "diary": false}, {"start": 692.71, "end": 695.27, "text": "जो गरम था, वो बर्फ़ ने लिया…", "who": "", "voice": "narrator", "diary": false}, {"start": 695.72, "end": 698.37, "text": "जो ठंडा बचा, चरवाहा ले चला…", "who": "", "voice": "narrator", "diary": false}, {"start": 698.82, "end": 701.83, "text": "राजुला के देस, मालूशाही की राह…", "who": "", "voice": "narrator", "diary": false}, {"start": 702.53, "end": 703.24, "text": "वो रुक गईं।", "who": "", "voice": "narrator", "diary": false}, {"start": 703.94, "end": 704.33, "text": "आगे?", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 704.53, "end": 706.53, "text": "शाओनी ने उनसे फुसफुसाकर कहा।", "who": "", "voice": "narrator", "diary": false}, {"start": 706.98, "end": 708.57, "text": "कमला देवी ने आँखें खोलीं।", "who": "", "voice": "narrator", "diary": false}, {"start": 708.77, "end": 710.25, "text": "आगे नहीं है, बेटी।", "who": "कमला देवी", "voice": "kamla", "diary": false}, {"start": 710.25, "end": 712.54, "text": "प्रताप ने कभी आगे नहीं गाया।", "who": "कमला देवी", "voice": "kamla", "diary": false}, {"start": 712.54, "end": 713.61, "text": "मैं पूछती थी।", "who": "कमला देवी", "voice": "kamla", "diary": false}, {"start": 713.61, "end": 714.92, "text": "वो बस… हँसता था।", "who": "कमला देवी", "voice": "kamla", "diary": false}, {"start": 715.37, "end": 718.61, "text": "मैंने उसे धीरे-धीरे दोहराया, अपने लिए भी,", "who": "", "voice": "narrator", "diary": false}, {"start": 718.61, "end": 720.97, "text": "उतना ही, जितना किसी और के लिए।", "who": "", "voice": "narrator", "diary": false}, {"start": 721.17, "end": 723.88, "text": "जो गरम था, वो बर्फ़ ने लिया।", "who": "", "voice": "narrator", "diary": false}, {"start": 723.88, "end": 726.77, "text": "जो ठंडा बचा, वो चरवाहा ले गया।", "who": "", "voice": "narrator", "diary": false}, {"start": 726.97, "end": 728.4, "text": "मैं शाओनी की तरफ़ मुड़ा।", "who": "", "voice": "narrator", "diary": false}, {"start": 728.6, "end": 729.82, "text": "दो चीज़ें।", "who": "", "voice": "narrator", "diary": false}, {"start": 729.82, "end": 730.68, "text": "एक गरम।", "who": "", "voice": "narrator", "diary": false}, {"start": 730.68, "end": 731.66, "text": "एक ठंडी।", "who": "", "voice": "narrator", "diary": false}, {"start": 732.11, "end": 733.29, "text": "और ठंडी वाली।", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 733.49, "end": 734.5, "text": "शाओनी ने कहा,", "who": "", "voice": "narrator", "diary": false}, {"start": 734.7, "end": 736.23, "text": "चरवाहे ले गए।", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 736.23, "end": 736.82, "text": "कहीं।", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 736.82, "end": 738.46, "text": "राजुला के देस।", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 738.91, "end": 741.28, "text": "क्षितिज ने हम दोनों की तरफ़ बारी-बारी से देखा।", "who": "", "voice": "narrator", "diary": false}, {"start": 741.48, "end": 742.36, "text": "राजुला कौन?", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 742.81, "end": 746.31, "text": "गब्बर और कमला देवी, दोनों मुड़े, और उसे ऐसे घूरा,", "who": "", "voice": "narrator", "diary": false}, {"start": 746.31, "end": 748.53, "text": "जैसे उसने पूछ लिया हो, राम कौन।", "who": "", "voice": "narrator", "diary": false}, {"start": 748.98, "end": 750.26, "text": "राजुला-मालूशाही।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 750.46, "end": 751.48, "text": "गब्बर ने उसे बताया।", "who": "", "voice": "narrator", "diary": false}, {"start": 751.68, "end": 754.5, "text": "कुमाऊँ की सबसे बड़ी प्रेम कहानी।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 754.5, "end": 759.34, "text": "एक लड़की, जो पहाड़ पार करके अपने राजा को ढूँढने चली गई।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 759.79, "end": 761.32, "text": "और उसका देस कहाँ है?", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 761.77, "end": 763.2, "text": "गब्बर ने मुँह खोला।", "who": "", "voice": "narrator", "diary": false}, {"start": 763.2, "end": 765.92, "text": "फिर माथे पर बल डाले, और बंद कर लिया।", "who": "", "voice": "narrator", "diary": false}, {"start": 766.37, "end": 767.15, "text": "पक्का नहीं पता।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 767.35, "end": 768.06, "text": "उसने माना।", "who": "", "voice": "narrator", "diary": false}, {"start": 768.26, "end": 769.92, "text": "कुमाऊँ में कहीं ऊपर।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 769.92, "end": 772.08, "text": "हर गाँव कहता है, हमारा था।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 772.53, "end": 778.49, "text": "क्षितिज ने लिख लिया, उस पर गोला बनाया, और उसके बग़ल में एक बड़ा सा क्वेश्चन मार्क बनाया,", "who": "", "voice": "narrator", "diary": false}, {"start": 778.49, "end": 782.15, "text": "जैसे वो तब करता है, जब कोई क्लू असली हो, लेकिन बंद हो।", "who": "", "voice": "narrator", "diary": false}, {"start": 783.65, "end": 787.1, "text": "जब हम जाने के लिए उठे, मैंने दूर नीचे,", "who": "", "voice": "narrator", "diary": false}, {"start": 787.1, "end": 791.65, "text": "जुम्मा के रोड हेड पर, एक सफ़ेद एस-यू-वी खड़ी देखी।", "who": "", "voice": "narrator", "diary": false}, {"start": 791.65, "end": 793.92, "text": "और रास्ते पर ऊपर आता हुआ,", "who": "", "voice": "narrator", "diary": false}, {"start": 793.92, "end": 800.37, "text": "आधे ख़ाली गाँव और खुरचे हुए पहाड़ को ख़ुशी-ख़ुशी फ़िल्म करता हुआ… गोलू।", "who": "", "voice": "narrator", "diary": false}, {"start": 800.82, "end": 801.97, "text": "घोस्ट फ़ैमिली!", "who": "गोलू", "voice": "golu", "diary": false}, {"start": 801.97, "end": 805.66, "text": "द्रोणागिरी, जहाँ हनुमान जी को भी एंट्री नहीं!", "who": "गोलू", "voice": "golu", "diary": false}, {"start": 805.66, "end": 807.38, "text": "क्या यहाँ उनकी आत्मा…", "who": "गोलू", "voice": "golu", "diary": false}, {"start": 808.08, "end": 809.3, "text": "कमला देवी खड़ी हुईं।", "who": "", "voice": "narrator", "diary": false}, {"start": 810.0, "end": 811.94, "text": "वो धीरे-धीरे खड़ी हुईं,", "who": "", "voice": "narrator", "diary": false}, {"start": 811.94, "end": 815.48, "text": "एक हाथ पत्थर की दीवार पर रखे, और उसे घूरा।", "who": "", "voice": "narrator", "diary": false}, {"start": 815.48, "end": 817.41, "text": "उसकी रिंग लाइट को नहीं।", "who": "", "voice": "narrator", "diary": false}, {"start": 817.41, "end": 822.97, "text": "पहले उसकी टोपी को, वो फीकी नीली ऊनी टोपी, एक लंबे, अजीब मोमेंट तक,", "who": "", "voice": "narrator", "diary": false}, {"start": 822.97, "end": 827.44, "text": "जैसे आप किसी ऐसी चीज़ को देखते हैं, जो किसी और की हो।", "who": "", "voice": "narrator", "diary": false}, {"start": 827.44, "end": 828.95, "text": "फिर उसके चेहरे को।", "who": "", "voice": "narrator", "diary": false}, {"start": 828.95, "end": 830.8, "text": "उनकी आँखें सिकुड़ गईं।", "who": "", "voice": "narrator", "diary": false}, {"start": 830.8, "end": 832.07, "text": "उनके होंठ हिले।", "who": "", "voice": "narrator", "diary": false}, {"start": 832.52, "end": 837.2, "text": "फिर वो बोलीं, बहुत साफ़-साफ़, एक बूढ़ी औरत की आवाज़ में,", "who": "", "voice": "narrator", "diary": false}, {"start": 837.2, "end": 840.04, "text": "जो किसी ऐसे बच्चे को पहचान रही हो,", "who": "", "voice": "narrator", "diary": false}, {"start": 840.04, "end": 843.47, "text": "जिसे उसने कभी ख़ुबानी चुराने पर डाँटा था।", "who": "", "voice": "narrator", "diary": false}, {"start": 843.92, "end": 844.47, "text": "गौरव?", "who": "कमला देवी", "voice": "kamla", "diary": false}, {"start": 845.17, "end": 846.37, "text": "गोलू जम गया।", "who": "", "voice": "narrator", "diary": false}, {"start": 847.07, "end": 848.47, "text": "ये बस एक सेकंड चला।", "who": "", "voice": "narrator", "diary": false}, {"start": 848.47, "end": 850.6, "text": "फिर वो हँसा, ज़्यादा ज़ोर से,", "who": "", "voice": "narrator", "diary": false}, {"start": 850.6, "end": 853.39, "text": "ज़्यादा चमकीला, और उनसे चिल्लाकर बोला,", "who": "", "voice": "narrator", "diary": false}, {"start": 853.59, "end": 854.66, "text": "नहीं, दादी!", "who": "गोलू", "voice": "golu", "diary": false}, {"start": 854.66, "end": 855.53, "text": "मैं गोलू!", "who": "गोलू", "voice": "golu", "diary": false}, {"start": 855.53, "end": 856.5, "text": "दिल्ली से!", "who": "गोलू", "voice": "golu", "diary": false}, {"start": 856.5, "end": 858.82, "text": "लाइक और सब्सक्राइब करना!", "who": "गोलू", "voice": "golu", "diary": false}, {"start": 859.02, "end": 865.9, "text": "वो मुड़ा, अभी भी फ़िल्म करता हुआ, बहुत तेज़ी से रास्ते पर वापस जुम्मा की तरफ़ उतर गया,", "who": "", "voice": "narrator", "diary": false}, {"start": 865.9, "end": 868.7, "text": "और एक बार भी पीछे मुड़कर नहीं देखा।", "who": "", "voice": "narrator", "diary": false}, {"start": 869.15, "end": 872.01, "text": "कमला देवी उसे जाते देखती रहीं।", "who": "", "voice": "narrator", "diary": false}, {"start": 872.01, "end": 874.38, "text": "उन्होंने और कुछ नहीं कहा।", "who": "", "voice": "narrator", "diary": false}, {"start": 874.38, "end": 877.61, "text": "बस वापस बैठीं, और अपनी सेम उठा ली।", "who": "", "voice": "narrator", "diary": false}, {"start": 878.06, "end": 881.81, "text": "लेकिन उनके हाथ, मैंने नोटिस किया… काँप रहे थे।", "who": "", "voice": "narrator", "diary": false}, {"start": 883.31, "end": 887.84, "text": "जब हम जोशीमठ में अपने गेस्टहाउस पहुँचे, अँधेरा हो चुका था।", "who": "", "voice": "narrator", "diary": false}, {"start": 887.84, "end": 893.16, "text": "दुखते शरीर, चुपचाप, हम उसकी छोटी सी लॉबी में घुसे, प्लास्टिक के फूल,", "who": "", "voice": "narrator", "diary": false}, {"start": 893.16, "end": 897.23, "text": "और एक टीवी पर क्रिकेट मैच, जिसे कोई नहीं देख रहा था।", "who": "", "voice": "narrator", "diary": false}, {"start": 897.68, "end": 901.27, "text": "हीटर के पास वाली आरामकुर्सी पर कोई बैठा था।", "who": "", "voice": "narrator", "diary": false}, {"start": 901.27, "end": 902.86, "text": "नेवी क्वार्टर-ज़िप।", "who": "", "voice": "narrator", "diary": false}, {"start": 902.86, "end": 903.78, "text": "महँगी घड़ी।", "who": "", "voice": "narrator", "diary": false}, {"start": 903.78, "end": 906.46, "text": "बग़ल में टेबल पर आधी पी हुई चाय।", "who": "", "voice": "narrator", "diary": false}, {"start": 906.91, "end": 911.12, "text": "उसकी गोद में, खुली हुई, एक ब्राउन लेदर नोटबुक थी,", "who": "", "voice": "narrator", "diary": false}, {"start": 911.12, "end": 914.65, "text": "जिसके कवर के अंदर छपा था: सर, लिखते रहना।", "who": "", "voice": "narrator", "diary": false}, {"start": 915.1, "end": 918.3, "text": "रोहन सहगल ने ऊपर देखा, और मुझे ऐसे मुस्कुराया,", "who": "", "voice": "narrator", "diary": false}, {"start": 918.3, "end": 921.01, "text": "जैसे कोई पुराने दोस्त को मुस्कुराता है।", "who": "", "voice": "narrator", "diary": false}, {"start": 921.46, "end": 923.48, "text": "मम्मी कहती हैं, स्वेटर पहनो।", "who": "रोहन", "voice": "rohan", "diary": false}, {"start": 923.68, "end": 927.5, "text": "उसने एक गर्मजोशी भरी, मज़े लेती आवाज़ में ज़ोर से पढ़ा।", "who": "", "voice": "narrator", "diary": false}, {"start": 927.7, "end": 929.98, "text": "मम्मी कहती हैं, भूतों के पीछे मत भागो।", "who": "रोहन", "voice": "rohan", "diary": false}, {"start": 929.98, "end": 931.78, "text": "मम्मी ने आज चार बार फ़ोन किया।", "who": "रोहन", "voice": "rohan", "diary": false}, {"start": 931.98, "end": 933.25, "text": "उसने एक पेज पलटा।", "who": "", "voice": "narrator", "diary": false}, {"start": 933.45, "end": 936.09, "text": "आप उनके बारे में बहुत लिखते हैं, प्रोफ़ेसर।", "who": "रोहन", "voice": "rohan", "diary": false}, {"start": 936.09, "end": 937.01, "text": "बहुत प्यारा है।", "who": "रोहन", "voice": "rohan", "diary": false}, {"start": 937.01, "end": 937.45, "text": "सच में।", "who": "रोहन", "voice": "rohan", "diary": false}, {"start": 937.9, "end": 940.92, "text": "उसके पीछे, डाइनिंग रूम का दरवाज़ा भरता हुआ,", "who": "", "voice": "narrator", "diary": false}, {"start": 940.92, "end": 942.61, "text": "भल्ला हाथ बाँधे खड़ा था।", "who": "", "voice": "narrator", "diary": false}, {"start": 943.06, "end": 945.45, "text": "रोहन ने मेरी नोटबुक धीरे से बंद की,", "who": "", "voice": "narrator", "diary": false}, {"start": 945.45, "end": 948.86, "text": "और उसे अपने घुटने पर रख दिया, किनारे से एकदम सीधा।", "who": "", "voice": "narrator", "diary": false}, {"start": 949.31, "end": 951.26, "text": "चलिए, ये बोरिंग तरीक़े से नहीं करते।", "who": "रोहन", "voice": "rohan", "diary": false}, {"start": 951.46, "end": 953.83, "text": "उसने कहा, अभी भी मुझसे।", "who": "", "voice": "narrator", "diary": false}, {"start": 954.03, "end": 954.3, "text": "कल।", "who": "रोहन", "voice": "rohan", "diary": false}, {"start": 954.3, "end": 954.65, "text": "औली।", "who": "रोहन", "voice": "rohan", "diary": false}, {"start": 954.65, "end": 956.52, "text": "स्की स्लोप के टॉप पर।", "who": "रोहन", "voice": "rohan", "diary": false}, {"start": 956.52, "end": 957.49, "text": "ग्यारह बजे।", "who": "रोहन", "voice": "rohan", "diary": false}, {"start": 957.49, "end": 960.16, "text": "आप मेरी नोटबुक लाइए, और वो सब,", "who": "रोहन", "voice": "rohan", "diary": false}, {"start": 960.16, "end": 965.93, "text": "जो द्रोणागिरी की उस प्यारी सी बूढ़ी अम्मा ने आज आपको गाकर सुनाया।", "who": "रोहन", "voice": "rohan", "diary": false}, {"start": 965.93, "end": 968.33, "text": "हाँ, मुझे पता है, आप गए थे।", "who": "रोहन", "voice": "rohan", "diary": false}, {"start": 968.33, "end": 973.92, "text": "आप जो कुछ करते हैं, मुझे उसके लगभग चार घंटे बाद पता चल जाता है।", "who": "रोहन", "voice": "rohan", "diary": false}, {"start": 974.12, "end": 975.31, "text": "वो फिर मुस्कुराया।", "who": "", "voice": "narrator", "diary": false}, {"start": 975.51, "end": 977.12, "text": "मैं आपकी वापस दे दूँगा।", "who": "रोहन", "voice": "rohan", "diary": false}, {"start": 977.12, "end": 979.3, "text": "मम्मी का नंबर, पोएट्री, सब कुछ।", "who": "रोहन", "voice": "rohan", "diary": false}, {"start": 979.3, "end": 983.46, "text": "और फिर आप घर जाइए और ये भूल जाइए… और मैं उन्हें भूल जाऊँगा।", "who": "रोहन", "voice": "rohan", "diary": false}, {"start": 983.91, "end": 989.24, "text": "वो उठा, अपनी चाय ख़त्म की, और हमारे पास से दरवाज़े तक गया,", "who": "", "voice": "narrator", "diary": false}, {"start": 989.24, "end": 993.02, "text": "इतने पास से, कि मुझे उसका कोलोन सूँघ गया।", "who": "", "voice": "narrator", "diary": false}, {"start": 993.02, "end": 996.15, "text": "दरवाज़े पर, वो रुका, और पीछे देखा।", "who": "", "voice": "narrator", "diary": false}, {"start": 996.6, "end": 998.35, "text": "ओह, और प्रोफ़ेसर?", "who": "रोहन", "voice": "rohan", "diary": false}, {"start": 998.35, "end": 999.6, "text": "अकेले आइएगा।", "who": "रोहन", "voice": "rohan", "diary": false}, {"start": 999.8, "end": 1001.68, "text": "उसकी नज़र शाओनी की तरफ़ गई।", "who": "", "voice": "narrator", "diary": false}, {"start": 1001.88, "end": 1004.8, "text": "आपकी दोस्त जैकेट्स के साथ बहुत होशियार हैं।", "who": "रोहन", "voice": "rohan", "diary": false}, {"start": 1004.8, "end": 1006.57, "text": "मैं ये नहीं जानना चाहूँगा,", "who": "रोहन", "voice": "rohan", "diary": false}, {"start": 1006.57, "end": 1009.28, "text": "कि स्की स्लोप्स के साथ वो क्या करती हैं।", "who": "रोहन", "voice": "rohan", "diary": false}, {"start": 1009.73, "end": 1011.08, "text": "दरवाज़ा बंद हुआ।", "who": "", "voice": "narrator", "diary": false}, {"start": 1011.08, "end": 1013.52, "text": "भल्ला उसके पीछे बाहर चला गया।", "who": "", "voice": "narrator", "diary": false}, {"start": 1013.52, "end": 1015.71, "text": "बाहर, एक इंजन स्टार्ट हुआ।", "who": "", "voice": "narrator", "diary": false}, {"start": 1016.16, "end": 1018.61, "text": "बहुत देर तक कोई नहीं हिला।", "who": "", "voice": "narrator", "diary": false}, {"start": 1018.61, "end": 1022.48, "text": "फिर शाओनी ने, बहुत धीरे से, वो सवाल पूछा,", "who": "", "voice": "narrator", "diary": false}, {"start": 1022.48, "end": 1027.1, "text": "जो अंदर आने के बाद से हम सबके दिमाग़ में बैठा था।", "who": "", "voice": "narrator", "diary": false}, {"start": 1027.55, "end": 1028.42, "text": "चार घंटे।", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 1028.62, "end": 1031.01, "text": "उसने हम सबको, एक-एक करके देखा।", "who": "", "voice": "narrator", "diary": false}, {"start": 1031.21, "end": 1033.25, "text": "उसे कैसे पता चला, हम द्रोणागिरी गए?", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 1033.7, "end": 1036.42, "text": "हममें से किसी ने एक-दूसरे की तरफ़ नहीं देखा।", "who": "", "voice": "narrator", "diary": false}, {"start": 1036.87, "end": 1042.55, "text": "और हम सबने, जुम्मा पर खड़ी एक सफ़ेद एस-यू-वी के बारे में सोचा।", "who": "", "voice": "narrator", "diary": false}, {"start": 1043.0, "end": 1044.18, "text": "क्षितिज की डायरी से।", "who": "", "voice": "narrator", "diary": true}, {"start": 1044.18, "end": 1045.43, "text": "डे सिक्स, द्रोणागिरी।", "who": "", "voice": "narrator", "diary": true}, {"start": 1045.88, "end": 1048.67, "text": "द्रोणागिरी अपने पहाड़ को पूजता है।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1048.67, "end": 1050.97, "text": "हनुमान उसका एक टुकड़ा ले गए।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1050.97, "end": 1053.76, "text": "उनकी रामलीला में हनुमान नहीं होते।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1053.76, "end": 1056.64, "text": "पार्थ भाई ने यहाँ चालीसा नहीं पढ़ी।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1056.64, "end": 1059.18, "text": "उन्होंने हनुमान जी से सॉरी कहा।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1059.18, "end": 1061.48, "text": "दोनों, मुझे लगता है, सही थे।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1061.93, "end": 1069.62, "text": "प्रताप सिंह रावत और दो दोस्त, उन्नीस सौ छियासठ के बसंत में बहुत जल्दी ऊपर गए,", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1069.62, "end": 1073.51, "text": "छह दिन बाद लौटे, महीनों तक बात नहीं की।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1073.51, "end": 1075.21, "text": "फिर एक गीत बनाया।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1075.66, "end": 1079.22, "text": "नया छंद: जो गरम था, वो बर्फ़ ने लिया।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1079.22, "end": 1081.82, "text": "जो ठंडा बचा, चरवाहा ले चला।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1081.82, "end": 1084.81, "text": "राजुला के देस, मालूशाही की राह।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1084.81, "end": 1085.78, "text": "दो चीज़ें।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1085.78, "end": 1088.67, "text": "एक गरम, शायद अभी भी बर्फ़ में।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1088.67, "end": 1090.5, "text": "एक ठंडी, ले जाई गई।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1090.5, "end": 1092.43, "text": "आर. को कौन सी चाहिए?", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1092.43, "end": 1095.32, "text": "क्या आर. को पता है, कि दो हैं?", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1095.77, "end": 1098.0, "text": "राजुला का देस: क्या?", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1098.0, "end": 1100.57, "text": "हर गाँव कहता है, हमारा।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1100.57, "end": 1101.47, "text": "पता करो।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1101.92, "end": 1104.99, "text": "कमला दादी ने गोलू को गौरव बुलाया।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1104.99, "end": 1109.19, "text": "उन्होंने पहले उसकी टोपी देखी, फिर उसका चेहरा।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1109.19, "end": 1109.93, "text": "वो भागा।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1109.93, "end": 1111.89, "text": "उनके हाथ काँप रहे थे।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1111.89, "end": 1113.47, "text": "वो उसे जानती हैं।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1113.47, "end": 1114.22, "text": "यहीं से।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1114.22, "end": 1117.02, "text": "और वो उस टोपी को भी जानती हैं।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1117.47, "end": 1121.69, "text": "आर. को चार घंटे बाद पता चल गया, कि हम द्रोणागिरी गए।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1121.69, "end": 1122.99, "text": "उसे किसने बताया?", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1122.99, "end": 1125.5, "text": "वहाँ और कोई था, तो सिर्फ़ गोलू।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1125.5, "end": 1129.56, "text": "दीदी कहती हैं: या कोई, जिसने जुम्मा पर बसंती देखी।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1129.56, "end": 1130.94, "text": "जल्दबाज़ी मत करो।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1130.94, "end": 1131.43, "text": "नोटेड।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1131.43, "end": 1133.21, "text": "जल्दबाज़ी नहीं कर रहा।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1133.21, "end": 1133.54, "text": "अभी।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1133.99, "end": 1137.15, "text": "और किसे पता था, कि हम द्रोणागिरी जा रहे हैं?", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1137.15, "end": 1137.51, "text": "महेश।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1137.51, "end": 1138.95, "text": "उसने बहुत सवाल पूछे।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1138.95, "end": 1139.31, "text": "महेश?", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1139.31, "end": 1139.67, "text": "नहीं।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1139.67, "end": 1141.54, "text": "वो गब्बर भैया का कज़िन है।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1141.54, "end": 1143.92, "text": "दोनों एक साइकिल पर स्कूल जाते थे।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1143.92, "end": 1144.78, "text": "काट रहा हूँ।", "who": "क्षितिज", "voice": "kshitij", "diary": true}], "scenes": [{"at": 22.89, "bed": "tender"}, {"at": 65.52, "bed": "night"}, {"at": 129.58, "bed": "roadday"}, {"at": 150.95, "bed": "dhaba"}, {"at": 257.11, "bed": "trek"}, {"at": 301.76, "bed": "legend"}, {"at": 356.94, "bed": "village"}, {"at": 432.7, "bed": "legend"}, {"at": 574.65, "bed": "tender"}, {"at": 623.33, "bed": "porch"}, {"at": 714.17, "bed": "discovery"}, {"at": 782.45, "bed": "golu"}, {"at": 806.88, "bed": "threat"}, {"at": 882.11, "bed": "night"}, {"at": 913.9, "bed": "threat"}, {"at": 1041.8, "bed": "diary"}, {"at": 1041.8, "bed": "diary"}], "hits": [{"at": 56.56, "fx": "sting"}, {"at": 135.79, "fx": "horn"}, {"at": 352.5, "fx": "sting"}, {"at": 428.22, "fx": "sting"}, {"at": 671.93, "fx": "flute"}, {"at": 800.67, "fx": "golu"}, {"at": 843.77, "fx": "sting"}, {"at": 906.76, "fx": "sting"}, {"at": 1009.58, "fx": "door"}, {"at": 1036.72, "fx": "sting"}, {"at": 1133.84, "fx": "sting"}], "next": {"label": "एपिसोड 7", "en": "The CIA Left Something on Our Mountain", "hook": "जोशीमठ की पुलिस, औली की एक बेंच, और एक ड्रोन, जिसने सब दिखा दिया।"}};
